(() => {
  const API = 'https://lnipoknkbjcxwnggzrnm.supabase.co';
  const KEY = 'sb_publishable_865CAmJ0g9wUj9dlCo6phQ_l5biuRKK';
  const session = () => { try { return JSON.parse(sessionStorage.getItem('diocese-dashboard-db-session') || '{}'); } catch { return {}; } };
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const card = () => [...document.querySelectorAll('.glass-card.page-card')].find(node => ['chapel information', 'church information'].includes((node.querySelector('h4')?.textContent || '').trim().toLowerCase()));
  const toast = message => { const node = document.createElement('div'); node.className = 'chapel-menu-toast'; node.textContent = message; document.body.append(node); setTimeout(() => node.remove(), 3200); };
  const request = async (path, options = {}) => {
    const user = session(); const response = await fetch(API + path, { ...options, headers: { apikey: KEY, Authorization: `Bearer ${user.accessToken || KEY}`, 'Content-Type': 'application/json', Prefer: 'return=representation', ...(options.headers || {}) } });
    const body = await response.text(); if (!response.ok) throw new Error(body || 'Request failed'); return body ? JSON.parse(body) : [];
  };
  const values = root => Object.fromEntries([...root.querySelectorAll('.mini-stat')].map(item => [(item.querySelector('span')?.textContent || '').trim(), { value: (item.querySelector('strong')?.textContent || '').trim().replace('—',''), note: (item.querySelector('small')?.textContent || '').trim() }]));
  async function profileId(root) {
    const user = session(); if (user.parish_id || user.parishId) return user.parish_id || user.parishId;
    const name = values(root)['Parish name']?.value; const email = user.email || values(root)['Contact']?.note;
    const filter = email ? `email=eq.${encodeURIComponent(email)}` : `parish_name=eq.${encodeURIComponent(name)}`;
    const rows = await request(`/rest/v1/parishes?select=id&${filter}&limit=1`); return rows[0]?.id;
  }
  function closeMenus() { document.querySelectorAll('.chapel-info-menu.is-open').forEach(node => node.classList.remove('is-open')); }
  function edit(root) {
    const data = values(root); const dialog = document.createElement('div'); dialog.className = 'chapel-info-dialog-backdrop';
    dialog.innerHTML = `<section class="chapel-info-dialog" role="dialog" aria-modal="true" aria-labelledby="chapel-info-title"><header><div><span>PARISH PROFILE</span><h3 id="chapel-info-title">Edit chapel information</h3></div><button type="button" data-close aria-label="Close">×</button></header><form><label>Parish name<input name="parish_name" required value="${escape(data['Parish name']?.value)}"></label><label>City<input name="city" value="${escape(data.City?.value)}"></label><label>Province<input name="province" value="${escape(data.City?.note)}"></label><label>Contact number<input name="contact_number" value="${escape(data.Contact?.value)}"></label><label>Email<input name="email" type="email" value="${escape(data.Contact?.note)}"></label><label class="chapel-info-dialog__wide">Address<input name="address" value="${escape(data.Address?.value)}"></label><footer><button type="button" class="secondary-action" data-close>Cancel</button><button type="submit" class="primary-action">Save changes</button></footer></form></section>`;
    const remove = () => dialog.remove(); dialog.addEventListener('click', event => { if (event.target === dialog || event.target.closest('[data-close]')) remove(); });
    dialog.querySelector('form').addEventListener('submit', async event => { event.preventDefault(); const button = event.currentTarget.querySelector('[type=submit]'); button.disabled = true; button.textContent = 'Saving…'; try { const id = await profileId(root); if (!id) throw new Error('This account is not linked to a parish profile.'); const payload = Object.fromEntries(new FormData(event.currentTarget)); await request(`/rest/v1/parishes?id=eq.${encodeURIComponent(id)}`, { method: 'PATCH', body: JSON.stringify(payload) }); Object.entries({ 'Parish name':'parish_name', City:'city', Contact:'contact_number', Address:'address' }).forEach(([label, key]) => { const item = [...root.querySelectorAll('.mini-stat')].find(node => node.querySelector('span')?.textContent.trim() === label); if (!item) return; item.querySelector('strong').textContent = payload[key] || '—'; if (label === 'City') item.querySelector('small').textContent = payload.province || ''; if (label === 'Contact') item.querySelector('small').textContent = payload.email || ''; }); remove(); toast('Chapel information updated.'); } catch (error) { button.disabled = false; button.textContent = 'Save changes'; toast(error.message || 'Could not save changes.'); } });
    document.body.append(dialog); dialog.querySelector('input')?.focus();
  }
  async function remove(root) { if (!confirm('Delete this parish profile? This action cannot be undone.')) return; try { const id = await profileId(root); if (!id) throw new Error('This account is not linked to a parish profile.'); await request(`/rest/v1/parishes?id=eq.${encodeURIComponent(id)}`, { method: 'DELETE' }); const remaining = await request(`/rest/v1/parishes?select=id&id=eq.${encodeURIComponent(id)}&limit=1`); if (remaining.length) throw new Error('The parish profile was not deleted. Run sql/parishes_delete_own_profile.sql in Supabase, then try again.'); sessionStorage.removeItem('diocese-dashboard-db-session'); root.remove(); toast('Parish profile deleted. Returning to sign in…'); setTimeout(() => { location.hash = 'login'; location.reload(); }, 700); } catch (error) { const message = String(error.message || ''); toast(/permission|policy|row-level|not authorized/i.test(message) ? 'Delete permission is missing. Run sql/parishes_delete_own_profile.sql in Supabase.' : (message || 'Could not delete the parish profile.')); } }
  function mount() { const root = card(); if (!root || root.dataset.chapelMenuMounted) return; const button = root.querySelector('.glass-card__header .mini-dots'); if (!button) return; root.dataset.chapelMenuMounted = 'true'; button.setAttribute('aria-haspopup', 'menu'); button.setAttribute('aria-expanded', 'false'); const menu = document.createElement('div'); menu.className = 'chapel-info-menu'; menu.setAttribute('role', 'menu'); menu.innerHTML = '<button type="button" role="menuitem" data-edit>Edit information</button><button type="button" role="menuitem" class="chapel-info-menu__delete" data-delete>Delete</button>'; button.after(menu); button.addEventListener('click', event => { event.stopPropagation(); const open = menu.classList.toggle('is-open'); button.setAttribute('aria-expanded', String(open)); }); menu.addEventListener('click', event => { if (event.target.closest('[data-edit]')) edit(root); if (event.target.closest('[data-delete]')) remove(root); closeMenus(); button.setAttribute('aria-expanded', 'false'); }); }
  document.addEventListener('click', closeMenus); setInterval(mount, 500); mount();
})();
